        public List<ResultCustomerlist> UpdateDoubleComm(int userId, string custDetail, bool isDoubleComm)
        {
            List<ResultCustomerlist> listResult = new List<ResultCustomerlist>();
            string[] custDetailArr = custDetail.Split(';');

            foreach (string customer in custDetailArr)
            {
                if (String.IsNullOrEmpty(customer)) continue;
                ResultCustomerlist resultCustomerList = new ResultCustomerlist();
                string[] detail = customer.Split('_');
                Result result = _customerSettingDataAccess.UpdateDoubleComm(userId, CastAide.AsInt32(detail[0]), isDoubleComm);
                resultCustomerList.Result = result;
                resultCustomerList.UserName = detail[1];
                listResult.Add(resultCustomerList);
            }
            return listResult;

        }
        public List<Currency> GetCurrencyList()
        {
            var result = new List<Currency>();

            try
            {
                result.Add(new Currency() { Value = -1, Name = "All" });

                var getData = base.GetCurrency();
                if (getData != null && getData.Rows.Count > 0)
                {
                    foreach (DataRow row in getData.Rows)
                    {
                        result.Add(new Currency()
                        {
                            Value = CastAide.AsInt32(row["ExchangeID"]),
                            Name = CastAide.AsString(row["Currency"])
                        });
                    }
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }
        private string GetStatusName(DataRow row)
        {
            var status = "";
            if (!CastAide.AsBoolean(row["enabled"]))
            {
                status = "Disabled";
            }
            else
            {
                if (CastAide.AsBoolean(row["closed"]))
                {
                    status = "Closed";
                }
                else if (CastAide.AsBoolean(row["suspended"]))
                {
                    status = "Suspended";
                }
                else if (DataUtils.IsExistKey(row, "isinternal") && CastAide.AsBoolean(row["isinternal"]))
                {
                    status = "Open";
                }
                else
                {
                    status = "Open";
                }
            }

            return status;
        }
        private string GetVirtualRate(double virtualRate)
        {
            double virRate = 0;
            virRate = virtualRate * 100;
            string strVirRate = string.Empty;
            if (virRate < 0)
            {
                strVirRate = virRate.ToString();
            }
            else if (virRate > 0)
            {
                strVirRate = "+" + virRate.ToString();
            }
            else
            {
                strVirRate = "--";
            }
            return strVirRate;
        }
